  "implementation": "def solve(case):
    import sys
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    if not nodes:
        return {'edges': [], 'total_weight': 0.0}
    # Build all mutual reachability edges
    edges = []
    for u, v, d in dist_list:
        if u > v:
            u, v = v, u
        weight = max(core[u], core[v], d)
        edges.append((weight, u, v))
    # Sort deterministically: weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    n = len(nodes)
    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append({'node1': u, 'node2': v, 'weight': weight})
            total += weight
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected')
    return {'edges': mst_edges, 'total_weight': total}"
